const config = $('CONFIG - Alterar variáveis').first().json.config;

const termosObrigatorios = config.termosObrigatorios.map(t => t.toLowerCase());

const emailsFiltrados = [];

for (const item of items) {
  const subject = item.json.subject || '';
  const body = item.json.bodyPreview || item.json.body?.content || item.json.text || '';
  const receivedDateTime = item.json.receivedDateTime || '';
  const from = item.json.from?.emailAddress?.address || item.json.from || '';

  const texto = `${subject} ${body}`.toLowerCase();
  const relevante = termosObrigatorios.some(t => texto.includes(t));

  if (!relevante) continue;

  emailsFiltrados.push({
    json: {
      config,
      email: {
        subject,
        body,
        receivedDateTime,
        from
      }
    }
  });
}

return emailsFiltrados;

const config = $('CONFIG - Alterar variáveis').first().json.config;
const todas = [];

for (const item of items) {
  let texto = '';

  if (item.json.output_text) {
    texto = item.json.output_text;
  } else if (item.json.output?.[0]?.content?.[0]?.text) {
    texto = item.json.output[0].content[0].text;
  } else {
    texto = JSON.stringify(item.json);
  }

  try {
    const parsed = JSON.parse(texto);
    const licitacoes = parsed.licitacoes || [];

    for (const lic of licitacoes) {
      if ((lic.score || 0) >= config.scoreMinimoParaEnviar && lic.classificacao !== 'Ignorar') {
        todas.push(lic);
      }
    }
  } catch (error) {
    todas.push({
      titulo: 'Erro ao interpretar resposta da IA',
      orgao: '',
      cidade_estado: '',
      modalidade: '',
      objeto: texto,
      prazo: '',
      valor_estimado: '',
      link: '',
      score: 0,
      classificacao: 'Erro',
      motivos_positivos: [],
      riscos: [error.message],
      recomendacao: 'Revisar manualmente.'
    });
  }
}

todas.sort((a, b) => (b.score || 0) - (a.score || 0));
const selecionadas = todas.slice(0, config.quantidadeMaximaRecomendacoes);

let html = `<h2>Resumo automático de licitações</h2>`;
html += `<p><strong>Data:</strong> ${new Date().toLocaleString('pt-BR')}</p>`;
html += `<p><strong>Total recomendado:</strong> ${selecionadas.length}</p>`;

if (selecionadas.length === 0) {
  html += `<p>Nenhuma licitação relevante foi encontrada com score mínimo de ${config.scoreMinimoParaEnviar}.</p>`;
} else {
  selecionadas.forEach((lic, index) => {
    html += `<hr>`;
    html += `<h3>${index + 1}. ${lic.titulo || 'Sem título'}</h3>`;
    html += `<p><strong>Score:</strong> ${lic.score}</p>`;
    html += `<p><strong>Classificação:</strong> ${lic.classificacao || ''}</p>`;
    html += `<p><strong>Órgão:</strong> ${lic.orgao || ''}</p>`;
    html += `<p><strong>Local:</strong> ${lic.cidade_estado || ''}</p>`;
    html += `<p><strong>Modalidade:</strong> ${lic.modalidade || ''}</p>`;
    html += `<p><strong>Objeto:</strong> ${lic.objeto || ''}</p>`;
    html += `<p><strong>Prazo:</strong> ${lic.prazo || ''}</p>`;
    html += `<p><strong>Valor estimado:</strong> ${lic.valor_estimado || ''}</p>`;

    if (lic.link) {
      html += `<p><strong>Link:</strong> <a href="${lic.link}">${lic.link}</a></p>`;
    }

    if (lic.motivos_positivos?.length) {
      html += `<p><strong>Motivos positivos:</strong></p><ul>`;
      lic.motivos_positivos.forEach(m => html += `<li>${m}</li>`);
      html += `</ul>`;
    }

    if (lic.riscos?.length) {
      html += `<p><strong>Riscos:</strong></p><ul>`;
      lic.riscos.forEach(r => html += `<li>${r}</li>`);
      html += `</ul>`;
    }

    html += `<p><strong>Recomendação:</strong> ${lic.recomendacao || ''}</p>`;
  });
}

html += `<hr>`;
html += `<p><em>Esta análise foi gerada automaticamente por IA e deve ser validada antes de qualquer decisão comercial, técnica ou jurídica.</em></p>`;

return [
  {
    json: {
      config,
      licitacoes: selecionadas,
      email: {
        to: config.emailDestino,
        from: config.emailRemetente,
        subject: config.assuntoEmail,
        html
      }
    }
  }
];
